const std = @import("std");

const KV = struct { key: u32, value: u32, occupied: bool };

pub fn main() !void {
    var table = [_]KV{ KV{ .key = 0, .value = 0, .occupied = false } } ** 8;

    const entries = [_]u32{ 10, 22, 31, 4, 15 };
    for (entries) |val| {
        var idx = val % 8;
        while (table[idx].occupied) {
            idx = (idx + 1) % 8;
        }
        table[idx] = KV{ .key = val, .value = val * 10, .occupied = true };
    }

    for (table) |kv| {
        if (kv.occupied) {
            std.debug.print("{}:{}\n", .{kv.key, kv.value});
        }
    }
}

